class Tool {
  final String executable = 'mytool';

  Future<Process> send(String message) =>
      Process.start(executable, ['--message=$message']);
}

Future<Process> start(String to) {
  final base = ['--store', 'data', '--json'];
  return Process.start('mytool', [...base, '--', to]);
}

class Tool {
  Tool(this.executable);

  final String executable;

  Future<Process> send(String message) =>
      Process.start(executable, ['--message=$message']);
}
